package com.example.rockblockbot

import kotlin.math.abs

/** Find an actual placement even when unexpected line clears make an added-cell
 * comparison impossible. Candidate boards are generated by the same rules as
 * the solver; never infer a displacement from just an occupied-cell count.
 */
object PlacementDiagnostics {
    data class Result(val dx: Int, val dy: Int, val row: Int, val col: Int,
                      val clearedLines: Int)

    fun findMatches(before: Long, piece: Piece, planRow: Int, planCol: Int,
                    after: Long): List<Result> {
        val matches = ArrayList<Result>()
        for (row in 0..(8-piece.height)) for (col in 0..(8-piece.width)) {
            val board = try { Solver.placeAndClear(before,piece,row,col) }
                        catch (_: IllegalArgumentException) { continue }
            if (board != after) continue
            val placed = before or piece.normalized.fold(0L) { mask, cell ->
                mask or (1L shl ((row+cell.r)*8+col+cell.c))
            }
            var cleared = 0
            for (r in 0..7) {
                val rowMask = 255L shl (r*8)
                if (placed and rowMask == rowMask) cleared++
            }
            for (c in 0..7) {
                var colMask = 0L
                for (r in 0..7) colMask = colMask or (1L shl (r*8+c))
                if (placed and colMask == colMask) cleared++
            }
            matches.add(Result(col-planCol,row-planRow,row,col,cleared))
        }
        return matches.sortedWith(compareBy({abs(it.dx)+abs(it.dy)}, {abs(it.dy)}, {abs(it.dx)}))
    }

    fun diagnose(before: Long, piece: Piece, planRow: Int, planCol: Int,
                 after: Long): String {
        val matches = findMatches(before,piece,planRow,planCol,after)
        if (matches.size == 1) {
            val m = matches.single()
            return if (m.dx==0 && m.dy==0) "Board matches preview; tray/verification timing differed."
            else "Piece landed ${m.dx} columns, ${m.dy} rows from preview" +
                 (if (m.clearedLines>0) "; cleared ${m.clearedLines} line(s)" else "")
        }
        if (matches.size>1) return "Several placements fit final board; correction is ambiguous."
        if (before==after) return "NO BOARD CHANGE: piece may have snapped back."
        return "Final board cannot be explained by one legal placement of this shape."
    }
}
